CREATE OR REPLACE FUNCTION public.no_private_birth_fields(payload jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE item record; child jsonb; BEGIN IF jsonb_typeof(payload)='object' THEN FOR item IN SELECT * FROM jsonb_each(payload) LOOP IF item.key = ANY(ARRAY['lat','lon','latitude','timezone','city','country','place','day','month','year','hour','minute','birthDate','birthTime','birthPlace']) THEN RETURN false; END IF; IF NOT public.no_private_birth_fields(item.value) THEN RETURN false; END IF; END LOOP; ELSIF jsonb_typeof(payload)='array' THEN FOR child IN SELECT value FROM jsonb_array_elements(payload) LOOP IF NOT public.no_private_birth_fields(child) THEN RETURN false; END IF; END LOOP; END IF; RETURN true; END $$;